DROP MATERIALIZED VIEW IF EXISTS ultra_credible_accounts;
CREATE MATERIALIZED VIEW ultra_credible_accounts AS
SELECT a.*
FROM accounts a
JOIN risk_and_moderation rm ON a.acct_ref = rm.acct_risk
WHERE (rm.risk_profile->'risk_scores'->>'credibility_score')::numeric > 0.9;
REFRESH MATERIALIZED VIEW ultra_credible_accounts;

